    [Theory]
    [MemberData(nameof(Vectors))]
    public async Task UpstreamVectorRoundTrips(string name, char direction, string hex)
    {
        byte[] expected = Convert.FromHexString(hex);
        if (direction == 'C')
        {
            ushort opcode = checked((ushort)BinaryPrimitives.ReadUInt32LittleEndian(expected.AsSpan(2, 4)));
            Assert.Equal(expected[..6], ProtocolPackets.ClientHeader(opcode, expected.Length - 6));
        }
        using var input = new MemoryStream(expected, writable: false);
        object message = direction == 'S'
            ? await ServerOpcodeReader.ReadUnencryptedAsync(input)
            : await ClientOpcodeReader.ReadUnencryptedAsync(input);
        Assert.Equal(expected.Length, input.Position);
        Assert.StartsWith(name.TrimEnd("0123456789".ToCharArray()), message.GetType().Name);
        using var output = new MemoryStream();
        string writerName = direction == 'S' ? "WriteUnencryptedServerAsync" : "WriteUnencryptedClientAsync";
        var write = message.GetType().GetMethod(writerName, new[] { typeof(Stream), typeof(CancellationToken) });
        Assert.NotNull(write);
        await (Task)write.Invoke(message, new object[] { output, CancellationToken.None })!;
        // The upstream cases below compare parsed messages: zlib may encode the
        // same body differently across runtimes and compression levels.
        if (name.StartsWith("SMSG_COMPRESSED_MOVES", StringComparison.Ordinal)
            || name is "SMSG_COMPRESSED_UPDATE_OBJECT0" or "CMSG_AUTH_SESSION0" or "CMSG_UPDATE_ACCOUNT_DATA1")
        {
            output.Position = 0;
            object second = direction == 'S'
                ? await ServerOpcodeReader.ReadUnencryptedAsync(output)
                : await ClientOpcodeReader.ReadUnencryptedAsync(output);
            Assert.Equal(message.GetType(), second.GetType());
            Assert.Equal(output.Length, output.Position);
            Assert.Equal(System.Text.Json.JsonSerializer.Serialize(message, message.GetType()),
                System.Text.Json.JsonSerializer.Serialize(second, second.GetType()));
        }
        else Assert.Equal(expected, output.ToArray());
    }
